python3 -I - <<'EOF'
import nbformat,re
nb=nbformat.read('analysis.ipynb',4)
for i in (25,29,33):
    for o in nb.cells[i].outputs:
        if o.output_type=='display_data' or o.output_type=='execute_result':
            h=o.data.get('text/html')
            if h:
                rows=re.findall(r'<tr.*?</tr>',h,re.S)
                print('--- cell',i)
                for r in rows:
                    print(' | '.join(re.sub(r'<.*?>','',c).strip() for c in re.findall(r'<t[hd].*?</t[hd]>',r,re.S)))
EOF
